  for (const [field, value, message] of [
    ["x", -641, /between -640 and 1280/],
    ["y", 1281, /between -640 and 1280/],
    ["scale", 0.049, /between 0.05 and 4/],
    ["rotation", 181, /between -180 and 180/],
  ] as const) {
