  if (pathsIds.has(workflow.technique)) return drawPaths(p, workflow);
  if (systemsIds.has(workflow.technique)) return drawSystems(p, workflow);
  if (materialsIds.has(workflow.technique)) return drawMaterials(p, workflow);
